WITH "set_loyal" AS (SELECT "t0"."customer_id" AS "key" FROM "sales"."orders" AS "t0" WHERE ("t0"."status" = 'DONE') AND ("t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00') AND ("t0"."customer_id" IS NOT NULL) GROUP BY "t0"."customer_id" HAVING COUNT(*) > 5) SELECT "t0"."customer_id" AS "customer_id", "t0"."full_name" AS "full_name", "t0"."segment" AS "segment" FROM "crm"."customers" AS "t0" WHERE ("t0"."customer_id" IN (SELECT "key" FROM "set_loyal")) LIMIT 50
